import type { ConfigContext, ExpoConfig } from "expo/config";

// Generated by design/build-tokens.ts (JSON, because this file cannot import TypeScript modules).
import tokens from "./src/theme/tokens.generated.json";
import { versionCodeFrom } from "./plugins/versionCode";

const version = "1.0.0";

// Google client IDs and URL schemes come from the environment (.env), never from the repository.
export default ({ config }: ConfigContext): ExpoConfig => ({
  ...config,
  name: "ChePagame",
  slug: "chepagame",
  version,
  orientation: "portrait",
  icon: "./assets/images/icon.png",
  scheme: "chepagame",
  userInterfaceStyle: "automatic",
  // Icons and splash are generated from design/ with `npm run icons`; colors come from the tokens.
  ios: {
    icon: "./assets/images/icon.png",
    bundleIdentifier: "com.chepagame.app",
  },
  android: {
    package: "com.chepagame.app",
    versionCode: versionCodeFrom(version),
    // Permissions added by libraries that the App never uses (feature 010): drawing over other
    // apps is only for the dev menu on old Android versions, and exports go through the system
    // share sheet, which needs no storage access. expo-secure-store adds the biometric ones for
    // requireAuthentication, which the App does not use.
    blockedPermissions: [
      "android.permission.SYSTEM_ALERT_WINDOW",
      "android.permission.READ_EXTERNAL_STORAGE",
      "android.permission.WRITE_EXTERNAL_STORAGE",
      "android.permission.USE_BIOMETRIC",
      "android.permission.USE_FINGERPRINT",
    ],
    adaptiveIcon: {
      backgroundColor: tokens.color.light.primary,
      foregroundImage: "./assets/images/android-icon-foreground.png",
      backgroundImage: "./assets/images/android-icon-background.png",
      monochromeImage: "./assets/images/android-icon-monochrome.png",
    },
    predictiveBackGestureEnabled: false,
  },
  plugins: [
    "expo-router",
    [
      "expo-splash-screen",
      {
        backgroundColor: tokens.color.light.background,
        image: "./assets/images/splash-icon.png",
        imageWidth: 120,
        dark: {
          backgroundColor: tokens.color.dark.background,
          image: "./assets/images/splash-icon.png",
        },
      },
    ],
    [
      "@react-native-google-signin/google-signin",
      {
        // The plugin validates this even for Android builds, and an empty value counts as missing.
        // It only matters for iOS, where it must be the real reversed iOS client ID.
        iosUrlScheme: process.env.GOOGLE_IOS_URL_SCHEME || "com.googleusercontent.apps.placeholder",
      },
    ],
    "expo-secure-store",
    "expo-localization",
    // Brand typeface (Sora, SIL OFL) embedded in the native build: no download at runtime.
    ["expo-font", { fonts: ["./assets/fonts/Sora-SemiBold.ttf", "./assets/fonts/Sora-Bold.ttf"] }],
    // Release signing from mobile/.env, R8 and resource shrinking (feature 010).
    "./plugins/withReleaseSigning",
  ],
  experiments: {
    typedRoutes: true,
    reactCompiler: true,
  },
  // EAS project ID: a public identifier, not a credential.
  extra: {
    eas: {
      projectId: "194f53ff-81df-496b-b952-dcd216efa4f3",
    },
  },
});
